#!/usr/bin/env python3
"""Generate the committed, dependency-free GitHub Pages site. Run with Python 3."""
from pathlib import Path
from html import escape
from urllib.parse import quote
import json
import struct
import math

ROOT = Path(__file__).resolve().parents[1]
SITE = 'https://vertifold.studio'
EMAIL = 'ztizzlegaming@gmail.com'
UPDATED = 'October 24, 2026'
DATE = '2026-10-24'
# Bundle the raster crops at standard favicon sizes for browser fallback.
icon_sizes = (16, 32, 48)
icon_images = [(ROOT / f'assets/favicon-{size}.png').read_bytes() for size in icon_sizes]
icon_offset = 6 + 16 * len(icon_sizes)
icon_directory = bytearray(struct.pack('<HHH', 0, 1, len(icon_sizes)))
for size, data in zip(icon_sizes, icon_images):
    icon_directory.extend(struct.pack('<BBBBHHII', size, size, 0, 0, 1, 32, len(data), icon_offset))
    icon_offset += len(data)
(ROOT / 'favicon.ico').write_bytes(bytes(icon_directory) + b''.join(icon_images))

GAMES = [
    dict(slug='color-surge', name='Color Surge', number='01', math='Graph coloring', status='Available now', tagline='Color the grid.\nSolve the surge.', description='A little color. A lot of possibility. Bring a network of power stations to life, making sure connected stations never share a color.', short='Bring the network to life. Color every station so no two neighbors share the same color.', concept='Graph coloring asks how to assign colors to vertices so that adjacent vertices have different colors. Color Surge turns that constraint into a puzzle: every connection shapes your next choice.', features=[('Find your colors', 'Choose a color for each power station. Every connected pair needs different colors, so think a few steps ahead.'), ('Make every move count', 'Plan your coloring to avoid unnecessary changes. Earn stars and coins as you work through the networks.'), ('Keep exploring', 'Learn with a guided tutorial, solve 50 predefined levels, and continue into procedurally generated puzzles.')]),
    dict(slug='traffic-tangle', name='Traffic Tangle', number='02', math='Planar graphs', status='In development', tagline='Less crossing.\nMore connecting.', description='A tangled network. A clearer way through. Move traffic lights and rearrange the roads until every connection has room to breathe.', short='Find order in the roadways. Rearrange the intersections until no two roads cross.', concept='A planar graph can be drawn on a flat surface without its edges crossing. Traffic Tangle makes finding that arrangement the challenge: move the intersections while keeping their connections.', features=[('See a way through', 'Study the crossings and look for a different arrangement. The same network can look very different when its intersections move.'), ('Untangle the roads', 'Drag traffic lights to reorganize the network. The goal is a layout where no two roads cross.'), ('Follow the development', 'Traffic Tangle is being developed for Android and iOS. Release details will appear here when they are ready.')]),
    dict(slug='cover-command', name='Cover Command', number='03', math='Vertex cover', status='In development', tagline='Small choices.\nTotal coverage.', description='Every connection needs a little attention. An upcoming strategy puzzle about choosing the right points to cover an entire network.', short='Choose your positions wisely. Cover every connection with a carefully selected set of vertices.', concept='A vertex cover is a set of vertices that touches every edge in a graph. A minimum vertex cover does that with the fewest vertices possible. That search for efficient coverage is the idea behind Cover Command.', features=[('Choose your positions', 'The concept: select vertices so that every connection has at least one selected endpoint.'), ('Think across the network', 'A well-placed choice can cover several connections. Look for the vertices that do the most work together.'), ('An idea taking shape', 'Cover Command is in early development, starting on Android. Gameplay and release plans are still taking shape.')])
]

def mail(subject, body=''):
    return 'mailto:' + EMAIL + '?subject=' + quote(subject) + ('&body=' + quote(body) if body else '')

def brand():
    return '<a class="brand" href="index.html" aria-label="Vertifold Studios home"><img src="assets/favicon-192.png" alt="" width="40" height="40"><span>Vertifold<small>Studios</small></span></a>'

def footer():
    games = ''.join(f'<a href="{g["slug"]}.html">{g["name"]}</a>' for g in GAMES)
    return f'''<footer class="footer wrap"><div class="footer-top"><div>{brand()}<p class="footer-copy">Small studio. Curious minds.<br>Puzzles with a mathematical twist.</p></div><div class="footer-links"><div><span class="label">The games</span>{games}</div><div><span class="label">Here to help</span><a href="support.html">Player support</a><a href="privacy.html">Privacy &amp; data</a><a href="{mail('Hello Vertifold Studios')}">Contact us</a></div></div></div><div class="footer-bottom"><span>© 2026 Vertifold Studios · Jordan Turley</span><span>Made for the joy of figuring it out.</span></div></footer>'''

def page(filename, title, description, body, cls='', noindex=False, schema=None, game_tabs=False):
    canonical = SITE + ('/' if filename == 'index.html' else '/' + filename)
    structured = {'@context':'https://schema.org','@type':'Organization','name':'Vertifold Studios','url':SITE,'email':EMAIL} if filename=='index.html' else schema
    html = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#0b1024"><title>{escape(title)}</title><meta name="description" content="{escape(description, quote=True)}"><link rel="canonical" href="{canonical}"><link rel="icon" href="favicon.ico" sizes="any"><link rel="icon" type="image/png" sizes="32x32" href="assets/favicon-32.png"><link rel="icon" type="image/png" sizes="192x192" href="assets/favicon-192.png"><link rel="apple-touch-icon" sizes="180x180" href="assets/apple-touch-icon.png"><link rel="stylesheet" href="assets/site.css"><meta property="og:type" content="website"><meta property="og:site_name" content="Vertifold Studios"><meta property="og:title" content="{escape(title, quote=True)}"><meta property="og:description" content="{escape(description, quote=True)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{SITE}/assets/social-card.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="Vertifold Studios — Small games. Big ideas."><meta name="twitter:card" content="summary_large_image">{'<meta name="robots" content="noindex">' if noindex else ''}{'<script type="application/ld+json">'+json.dumps(structured)+'</script>' if structured else ''}</head>
<body class="{cls}"><a class="skip" href="#main">Skip to content</a><header class="header wrap">{brand()}<nav class="nav" aria-label="Main navigation"><a href="index.html#games">Our games</a><a class="desktop" href="index.html#studio">The studio</a><a href="support.html">Support ↗</a></nav></header><main id="main" class="wrap">{body}</main>{footer()}{'<script src="assets/game-tabs.js" defer></script>' if game_tabs else ''}</body></html>'''
    (ROOT / filename).write_text(html.replace('><', '>\n<') + '\n', encoding='utf-8')

def art(g):
    slug = g['slug']
    if slug == 'color-surge':
        nodes=[(92,92,'#f4aa76'),(260,55,'#92bfff'),(425,100,'#c6a4e8'),(80,238,'#92bfff'),(260,200,'#d4d68b'),(440,245,'#f4aa76'),(170,343,'#f4aa76'),(355,350,'#92bfff')]
        edges=[(0,1),(1,2),(0,3),(0,4),(1,4),(2,4),(2,5),(3,4),(3,6),(4,5),(4,6),(4,7),(5,7),(6,7)]
        lines=''.join(f'<path d="M{nodes[a][0]} {nodes[a][1]} {nodes[b][0]} {nodes[b][1]}"/>' for a,b in edges)
        circles=''.join(f'<circle cx="{x}" cy="{y}" r="24" fill="{c}"/><circle cx="{x}" cy="{y}" r="8" fill="#1a2332"/>' for x,y,c in nodes)
        drawing=f'<g stroke="#91a6bf" stroke-width="2.5" fill="none">{lines}</g><g>{circles}</g>'
    elif slug == 'traffic-tangle':
        drawing='''<g stroke="#536e98" stroke-width="21" fill="none" stroke-linejoin="round"><path d="m100 100 310 210-300 20L390 85 245 350 100 100 390 85 410 310"/></g><g stroke="#d2dcf4" stroke-width="2" stroke-dasharray="8 8" fill="none"><path d="m100 100 310 210-300 20L390 85 245 350 100 100 390 85 410 310"/></g>'''+''.join(f'<circle cx="{x}" cy="{y}" r="22" fill="#78b9ff" stroke="#162442" stroke-width="7"/><circle cx="{x}" cy="{y}" r="5" fill="#162442"/>' for x,y in [(100,100),(410,310),(110,330),(390,85),(245,350)])
    else:
        nodes=[(100,100),(260,70),(420,130),(170,240),(350,260),(100,350),(420,350)]
        edges=[(0,1),(0,3),(1,2),(1,3),(1,4),(2,4),(3,4),(3,5),(4,6)]
        selected={1,3,4}
        lines=''.join(f'<path d="M{nodes[a][0]} {nodes[a][1]} {nodes[b][0]} {nodes[b][1]}"/>' for a,b in edges)
        circles=''.join((f'<circle cx="{x}" cy="{y}" r="40" fill="none" stroke="#ffd195" stroke-opacity=".2"/>' if i in selected else '')+f'<circle cx="{x}" cy="{y}" r="20" fill="{"#ffd195" if i in selected else "#302923"}" stroke="#ffd195" stroke-width="2"/>'+ (f'<path d="m{x-7} {y} 5 5 10-11" fill="none" stroke="#302923" stroke-width="2.5"/>' if i in selected else '') for i,(x,y) in enumerate(nodes))
        drawing=f'<g stroke="#b18f65" stroke-width="2" fill="none">{lines}</g>{circles}'
    return f'''<div class="game-art {slug}"><span class="art-index label">{g['number']} / {g['math']}</span><span class="status">{g['status']}</span><svg viewBox="0 0 520 420" role="img" aria-label="{escape(g['math'])} concept illustration for {g['name']}">{drawing}</svg></div>'''

def subnav(g, active):
    slug=g['slug']
    return '<nav class="subnav" aria-label="'+g['name']+' pages">'+''.join(f'<a href="{slug}{suffix}.html"'+(' aria-current="page"' if label==active else '')+f'>{label}</a>' for suffix,label in [('', 'Overview'),('-download','Download'),('-support','Support'),('-privacy','Privacy policy')])+'</nav>'

def crumbs(g, label=''):
    return f'<div class="breadcrumb"><a href="index.html#games">Our games</a> / <a href="{g["slug"]}.html">{g["name"]}</a>{" / "+label if label else ""}</div>'

def stores():
    return '''<div class="store-links"><a class="store-button" href="https://apps.apple.com/app/id6757683749" aria-label="Download Color Surge on the App Store"><svg viewBox="0 0 24 28" aria-hidden="true"><path fill="currentColor" d="M16 4c1-1 2-2.8 1.8-4-1.5.1-3.3 1-4.3 2.2-.9 1-1.7 2.7-1.5 4.1 1.6.1 3.1-.8 4-2.3ZM20.8 14.7c0-3 2.5-4.5 2.6-4.6-1.5-2.2-3.7-2.5-4.5-2.5-1.9-.2-3.7 1.1-4.7 1.1-1 0-2.5-1.1-4.1-1.1-2.1 0-4.1 1.3-5.2 3.1-2.2 3.8-.6 9.5 1.6 12.6 1 1.5 2.3 3.1 3.9 3 1.6-.1 2.2-1 4.2-1 1.9 0 2.5 1 4.2 1 1.7 0 2.8-1.5 3.8-3 .9-1.1 1.5-2.5 1.8-3.3-1.8-.8-3.6-2.5-3.6-5.3Z" transform="translate(-2 0)"/></svg><span><small>Download on the</small><strong>App Store</strong></span></a><a class="store-button" href="https://play.google.com/store/apps/details?id=com.jordanturley.colorsurge" aria-label="Get Color Surge on Google Play"><svg viewBox="0 0 24 28" aria-hidden="true"><path d="M2 1v26l22-13Z" fill="none" stroke="currentColor" stroke-width="1.6"/><path d="m2 1 14 18M2 27 16 9" fill="none" stroke="currentColor" stroke-width="1.4"/></svg><span><small>Get it on</small><strong>Google Play</strong></span></a></div>'''

# A regular hexagon with alternating triangular connections shares one center
# with the stationary mark and the CSS rotation origin.
hero_center = (260, 212.5)
hero_points = [
    (hero_center[0] + 164 * math.cos(math.radians(-90 + i * 60)),
     hero_center[1] + 164 * math.sin(math.radians(-90 + i * 60)))
    for i in range(6)
]
def hero_polygon(indices):
    return 'M' + ' L'.join(f'{hero_points[i][0]:.3f} {hero_points[i][1]:.3f}' for i in indices) + ' Z'
hero_edges = ''.join(f'<path d="{hero_polygon(indices)}"/>' for indices in [(0, 1, 2, 3, 4, 5), (0, 2, 4), (1, 3, 5)])
hero_edges += ''.join(
    f'<path d="M{x:.3f} {y:.3f} L{hero_center[0]} {hero_center[1]}"/>'
    for x, y in hero_points
)
hero_nodes = ''.join(f'<circle cx="{x:.3f}" cy="{y:.3f}" r="22"/>' for x, y in hero_points)
hero_dots = ''.join(f'<circle cx="{hero_points[i][0]:.3f}" cy="{hero_points[i][1]:.3f}" r="7" fill="#12264b"/>' for i in (0, 2, 4))
hero_svg=f'''<svg viewBox="0 0 520 425" role="img" aria-label="A symmetric rotating network around a centered Vertifold mark"><g fill="none" stroke="#668dcc" stroke-width="1"><circle cx="260" cy="212.5" r="173" stroke-dasharray="3 8"/><circle cx="260" cy="212.5" r="132" stroke-opacity=".35"/></g><g class="orbit"><g stroke="#5276b3" stroke-width="2" fill="none">{hero_edges}</g><g fill="#78b9ff" stroke="#101a38" stroke-width="9">{hero_nodes}</g>{hero_dots}</g><circle cx="260" cy="212.5" r="45" fill="#92bfff" stroke="#101a38" stroke-width="9"/><path d="m242 197.5 18 30 18-30m-27 0 9 15 9-15" stroke="#12264b" stroke-width="3" stroke-linejoin="round" fill="none"/></svg>'''

cards=''.join(f'''<article class="game-card {g['slug']}">{art(g)}<div class="game-info"><span class="label">{g['math']}</span><h3>{g['name']}</h3><p>{g['short']}</p><a href="{g['slug']}.html">Explore {g['name']} <span aria-hidden="true">↗</span></a></div></article>''' for g in GAMES)
page('index.html','Vertifold Studios — Small games. Big ideas.','Discover mobile puzzle games inspired by graph theory: Color Surge, Traffic Tangle, and Cover Command. Small games. Big ideas.',f'''<section class="hero"><div class="hero-copy"><div class="eyebrow">Independent mobile game studio</div><h1>Small games.<br><span class="tagline-line">Big <em>ideas.</em></span></h1><p>We turn curious mathematical ideas into satisfying little puzzles. Easy to pick up. Plenty to figure out.</p><div class="actions"><a class="button primary" href="#games">Find your next puzzle <span aria-hidden="true">↘</span></a></div><span class="micro">Made for curious minds, one connection at a time.</span></div><div class="hero-visual"><div class="visual-label label"><span>Ideas, interconnected.</span><span>Fig. 01</span></div>{hero_svg}<div class="visual-caption"><span>GRAPH THEORY → PLAY</span><span>VERTIFOLD / STUDIOS</span></div></div></section><section class="section" id="games"><div class="section-heading"><div><div class="eyebrow">Our little universe</div><h2>New puzzles. Endless curiosity.</h2></div><p>A growing collection of mobile puzzles, each with a different way to see the network.</p></div><div class="game-grid">{cards}</div></section><section class="section about" id="studio"><div><div class="eyebrow">Meet Vertifold</div><h2>Good puzzles start<br>with a simple idea.</h2></div><div class="about-copy"><p>Vertifold Studios is an independent mobile game studio founded by Jordan Turley. We make games inspired by graph theory: the mathematics of points, connections, and the surprising things they can do together.</p><p>No math degree required. Just a little curiosity and the satisfaction of that moment when everything clicks.</p><div class="principles"><div><h3>Simple rules. Room to think.</h3><p>Understand the goal in a moment. Discover the possibilities as you play.</p></div><div><h3>Real ideas. Playful worlds.</h3><p>Explore coloring, planarity, and coverage through puzzles you can put your hands on.</p></div></div></div></section><section class="contact-band"><div><h2>A question, a puzzle, a hello?</h2><p>Find help with a game, ask about your data, or get in touch with the studio.</p></div><a class="button" href="support.html">We’re here to help <span aria-hidden="true">↗</span></a></section>''')

for g in GAMES:
    slug=g['slug']; name=g['name']; available=slug=='color-surge'
    features=''.join(f'<div class="feature"><span class="label">0{i+1}</span><h3>{h}</h3><p>{p}</p></div>' for i,(h,p) in enumerate(g['features']))
    note='' if available else '<p class="micro">In development. Concept illustrations; not gameplay screenshots. Features may change.</p>'
    button='Get Color Surge' if available else 'Release status'
    icon='<img class="game-icon" src="assets/color-surge.png" alt="" width="42" height="42">' if available else ''
    overview_hero = crumbs(g)+f'''<section class="hero game-hero"><div class="hero-copy"><div class="eyebrow">{g['status']} · {g['math']}</div><h1>{g['tagline'].replace(chr(10),'<br>')}</h1><h2 style="font-size:1.6rem;letter-spacing:-.02em">{icon}{name}</h2><p>{g['description']}</p><div class="actions"><a class="button primary" href="{slug}-download.html">{button} <span aria-hidden="true">↗</span></a><a class="text-link" href="{slug}-support.html">Game support</a></div>{note}</div>{art(g)}</section>'''
    overview_content = f'''<section class="section"><div class="section-heading"><h2>{'A small puzzle. A bright idea.' if available else 'A different kind of connection.'}</h2></div><div class="feature-grid">{features}</div></section><section class="math-note"><div><div class="eyebrow">Behind the puzzle</div><h2>{g['math']},<br>made playable.</h2></div><div><p>{g['concept']}</p><a class="text-link" href="https://en.wikipedia.org/wiki/{ {'color-surge':'Graph_coloring','traffic-tangle':'Planar_graph','cover-command':'Vertex_cover'}[slug]}">Explore the mathematics ↗</a></div></section><section class="section"><div class="contact-band"><div><h2>{'Ready to make the connections?' if available else 'Something to look forward to.'}</h2><p>{'Find Color Surge on iPhone, iPad, and Android.' if available else 'Check the download page for the latest release status.'}</p></div><a class="button" href="{slug}-download.html">{button} ↗</a></div></section>'''
    platform_note='Traffic Tangle is being developed for Android and iOS. There is no public download yet.' if slug=='traffic-tangle' else 'Cover Command is in early development, starting on Android. Platforms and release timing have not been announced.'
    download = stores()+'<p class="micro">Free to download · Contains ads<br>iPhone &amp; iPad: iOS 16+ · Android: Android 10+</p>' if available else f'<div class="status-panel"><h2>A new puzzle is taking shape.</h2><p>{platform_note}</p></div><div class="actions" style="justify-content:center"><a class="button primary" href="color-surge-download.html">Play Color Surge while you wait ↗</a></div>'
    page(slug+'-download.html','Download '+name+' — Vertifold Studios',('Get '+name+' for iPhone, iPad, and Android. Official App Store and Google Play links.' if available else 'Check the release status of '+name+', an upcoming graph-inspired puzzle from Vertifold Studios.'),f'''<section class="download-shell">{art(g)}<div class="eyebrow">{g['status']}</div><h1>{name}</h1><p>{g['short']}</p>{download}<nav class="download-utility" aria-label="{name} links"><a href="{slug}.html">About the game</a><a href="{slug}-support.html">Support</a><a href="{slug}-privacy.html">Privacy policy</a></nav></section>''',slug)

    faq=[('Is '+name+' available to download?', 'Yes. Color Surge is available on the <a href="https://apps.apple.com/app/id6757683749">App Store</a> for iPhone and iPad and on <a href="https://play.google.com/store/apps/details?id=com.jordanturley.colorsurge">Google Play</a> for Android.' if available else platform_note),('How do I play?', 'Color each power station so that connected stations have different colors. Use the in-game tutorial to learn the controls and power-ups.' if available else ('The goal is to drag traffic lights until no roads cross. The tutorial in development builds introduces the controls.' if slug=='traffic-tangle' else 'The planned goal is to select vertices so that every connection touches at least one selected vertex. The game is in early development; final rules and controls may change.'))]
    if slug!='cover-command':
        faq += [('Where is my progress saved?', 'Progress, coins, stars, and power-ups are saved on your device. There is no Vertifold account or cross-platform cloud sync. Device backups may include app data depending on your system settings. We cannot restore local progress from a studio server.'),('How do I reset my progress?', 'Open the settings menu on the main screen and choose Reset Progress. This resets level progress, stars, coins, power-ups, and the daily reward streak. This action cannot be undone. To remove app storage, use Android’s Clear storage control or delete the app on iOS; offloading the app can keep its data.'),('An ad did not load, or my reward did not arrive. What can I do?', 'Check your connection and try again later. Ad availability varies, and a reward usually requires completing the rewarded ad. If the problem continues, email the game name, app version, device, approximate time, and what happened. Please do not send your advertising identifier.'),('How do I control advertising or tracking?', 'On iOS, review Settings → Privacy &amp; Security → Tracking. On Android, use the advertising privacy controls in your device settings. These choices do not necessarily remove ads or stop all ad-related processing. See the game’s privacy policy for details.')]
    faq += [('The app crashes or a puzzle looks wrong. How do I report it?', 'Try closing and reopening the app, checking for updates, and restarting your device. Avoid deleting the app as a first step because you may lose progress. Send us steps to reproduce the issue, your device and OS version, the app version, and the level number if relevant.'),('How do I report an inappropriate ad?', 'Use the ad’s report or information control when available. You can also email us the advertiser, approximate time, device, and a screenshot with personal information removed. We can investigate reports but do not directly control every ad served by the advertising provider.'),('How do I ask about privacy or delete data?', f'Visit the <a href="{slug}-privacy.html#choices">privacy choices and deletion section</a>. You can also email us with “{name} privacy request” in the subject. There are no player accounts to delete.')]
    faqs=''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in faq)
    supportbody=crumbs(g,'Support')+f'''<div class="legal-hero"><div class="eyebrow">Player support</div><h1>{name}<br>Help is a connection away.</h1><p>Questions, a tricky bug, or feedback? Get in touch with the person making the game.</p></div>'''+subnav(g,'Support')+f'''<section class="section support-grid"><div class="support-card"><h2>Talk to the studio.</h2><p>Contact Jordan Turley at Vertifold Studios for game help, feedback, or to report an inappropriate advertisement.</p><p><a href="{mail(name+' support', 'Game: '+name+chr(10)+'App version: '+chr(10)+'Device and OS: '+chr(10)+'Level (if relevant): '+chr(10)+'What happened: '+chr(10))}">{EMAIL}</a></p><p class="micro">Include “{name} support” in your subject. We read every request; response times may vary.</p></div><div class="support-card"><h2>A few helpful details.</h2><ul><li>Device model, operating system, and app version</li><li>Level number and what you expected to happen</li><li>Steps to reproduce the issue</li><li>A screenshot, with personal information removed, if helpful</li></ul><p class="micro">Never send passwords, payment details, or advertising identifiers.</p></div></section><section class="prose"><h2>Common questions</h2>{faqs}</section><section class="section"><div class="notice">{'Color Surge is available now on iOS and Android.' if available else platform_note} For privacy questions, <a href="{slug}-privacy.html">read the {name} privacy policy</a>.</div></section>'''
    page(slug+'-support.html',name+' Support — Vertifold Studios','Contact Vertifold Studios for '+name+' support, troubleshooting, privacy questions, and feedback.',supportbody,slug)

    pre = '' if available else '<div class="notice">'+name+' is in development. This policy describes the current development builds and applies when you use a build provided by us. It will be updated if the released game handles data differently.</div>'
    policy=[
    ('who','Who we are',f'<p>This privacy policy explains how <strong>{name}</strong> handles information. The game is developed by <strong>Jordan Turley, operating as Vertifold Studios</strong>. Existing store listings or app identifiers may still show Jordan Turley or the earlier personal branding. For privacy questions, contact <a href="{mail(name+" privacy request")}">{EMAIL}</a>.</p>'+pre),
    ('information','Information and its uses',f'''<p><strong>Game data on your device.</strong> The app stores progress, completed levels, stars, coins, power-up inventory, daily reward dates, and preferences locally to operate the game and remember your choices. There is no player account, and we do not run a server that receives your saved game. Your device’s backup service may copy this information according to your settings.</p><p><strong>Advertising data.</strong> The app integrates Google AdMob (Google Mobile Ads SDK). When ads are requested or shown, Google and its advertising partners may process IP addresses (including approximate location inferred from them), device or advertising identifiers, ad views and interactions, and diagnostic or performance information. These are used to deliver and measure ads, provide advertising-related analytics, prevent abuse, and maintain the ad service. Data handled depends on platform, permissions, consent, SDK version, and ad configuration.</p><p><strong>Support correspondence.</strong> If you email us, we receive your email address, message, and any attachments you choose to send. We use these to answer you, investigate problems, and handle privacy requests. Do not include sensitive information in a bug report.</p><p>The app does not ask you to register, enter payment information, or grant access to your contacts, microphone, camera, or precise device location. We do not add a separate analytics or account service to the game; advertising SDKs perform their own measurement.</p>'''),
    ('sharing','Third parties and sharing','''<p>Google and advertising partners process ad-related information under their own policies and applicable agreements. We do not receive a copy of your full advertising profile. We use an email provider to receive and respond to support messages. Apple or Google may handle app distribution and device backups through their own services.</p><p>We do not sell saved game files or support messages, or provide them to data brokers. Ad-related sharing may be considered a “sale,” “sharing,” or targeted advertising under some privacy laws. Your available controls are described below. We may disclose information we hold if legally required or necessary to protect users, prevent abuse, or defend legal rights.</p><p>Third-party services must protect data as required by applicable law and our agreements; their independent practices are explained in their policies. Relevant resources:</p><ul><li><a href="https://policies.google.com/privacy">Google Privacy Policy</a></li><li><a href="https://policies.google.com/technologies/partner-sites">How Google uses information from apps and sites using its services</a></li><li><a href="https://support.google.com/admob/answer/9012903">Google AdMob advertising technology providers</a></li><li><a href="https://www.apple.com/legal/privacy/">Apple Privacy Policy</a></li></ul>'''),
    ('choices','Privacy choices and deletion',f'''<p><strong>iPhone and iPad:</strong> You can review or withdraw tracking permission in Settings → Privacy &amp; Security → Tracking. The app may request permission through Apple’s App Tracking Transparency prompt. Declining tracking does not prevent access to the game. Deleting the app removes its local storage; choosing “Offload App” may keep that storage.</p><p><strong>Android:</strong> Use your device’s advertising privacy controls to reset or delete an advertising ID or manage ad personalization, where available. Use Settings → Apps → {name} → Storage → Clear storage to remove local app data; labels vary by device. Uninstalling also removes local app storage, but backup copies may remain.</p><p><strong>Backups:</strong> To remove cloud backup copies, manage the relevant backup through Apple or Google. Reinstalling the app may restore backed-up data. We cannot delete backups held under your personal platform account.</p><p><strong>Advertising:</strong> Device tracking or personalization choices do not necessarily remove ads or stop all ad-related data processing. Use the controls available on the ad itself or the provider’s privacy tools to manage provider-held information. Device tracking permission is separate from any regional consent choices.</p><p><strong>Contact us:</strong> Email <a href="{mail(name+" privacy or deletion request")}">{EMAIL}</a> with “{name} privacy request” to request access, correction, deletion, restriction, or an objection to processing of information we hold. No account is required. Explain what you want us to do; we may request limited information to verify the request. We can delete support correspondence we hold, subject to legal obligations, but cannot locate or remotely remove device-only saves or provider-held advertising records.</p><p>Depending on your location, you may also have rights to portability, withdrawal of consent, or opting out of targeted advertising, sale, or sharing. We will handle requests as required by applicable law. You may contact your local data protection authority if you have a concern.</p>'''),
    ('retention','Retention and security','''<p>Local game data remains until it is reset, cleared, or removed, subject to device backup behavior. We keep support messages while handling your request and for up to 12 months after it is resolved, unless you ask for earlier deletion or a legal obligation or ongoing dispute requires longer retention. Advertising providers set their own retention periods under their published policies; we cannot specify or control all of those periods.</p><p>We limit access to support correspondence and use the security features provided by our service providers. Google states that Mobile Ads SDK data is encrypted in transit. No storage or transmission method is completely secure. Service providers may process information outside your country, subject to their applicable safeguards.</p>'''),
    ('children','Children’s privacy',f'''<p>{name} is a general-audience puzzle game and is not specifically directed at children under 13. We do not knowingly ask children under 13 to provide personal information directly to us. Advertising services may process device-related data as described above; parents and guardians should review device privacy controls and supervise use as appropriate. Store age ratings describe content and do not mean that an app has no advertising data processing.</p><p>If you believe a child has sent us personal information, contact <a href="{mail(name+" children privacy concern")}">{EMAIL}</a> so we can investigate and delete information we hold where required. Please do not include additional sensitive information about a child in your initial message.</p>'''),
    ('updates','Policy updates and contact',f'''<p>We may update this policy when the game, service providers, or data practices change. The date at the top identifies the latest revision. Material changes requiring notice or consent will be handled as required by applicable law.</p><p><strong>Privacy contact:</strong> Jordan Turley · Vertifold Studios<br><a href="{mail(name+" privacy question")}">{EMAIL}</a><br><a href="{slug}-support.html">{name} support</a></p>''')]
    toc='<nav class="toc" aria-label="Privacy policy sections">'+''.join(f'<a href="#{i}">{h}</a>' for i,h,_ in policy)+'</nav>'
    sections=''.join(f'<section id="{i}"><h2>{h}</h2>{content}</section>' for i,h,content in policy)
    policybody=crumbs(g,'Privacy policy')+f'<div class="legal-hero"><div class="eyebrow">Privacy policy · {name}</div><h1>Your data.<br>A clearer picture.</h1><p>Effective and last updated: <time datetime="{DATE}">{UPDATED}</time></p><p>This policy covers {name} and its current mobile builds. The <a href="privacy.html#website">website privacy notice</a> describes visits to this site.</p></div>'+subnav(g,'Privacy policy')+f'<div class="legal-layout">{toc}<article class="prose" aria-label="{name} privacy policy">{sections}</article></div>'
    page(slug+'-privacy.html',name+' Privacy Policy — Vertifold Studios','Privacy policy for '+name+': local game data, advertising, support messages, retention, privacy choices, and deletion requests.',policybody,slug)

    # The same content powers the embedded views and public standalone pages.
    tab_items = [('overview', 'Overview', ''), ('download', 'Download', '-download'),
                 ('support', 'Support', '-support'), ('privacy', 'Privacy policy', '-privacy')]
    tab_links = ''.join(
        f'<a id="tab-{key}" href="{slug}{suffix}.html" data-tab="{key}"'
        + (' aria-current="page"' if key == 'overview' else '')
        + f'>{label}</a>' for key, label, suffix in tab_items
    )
    tab_nav = f'<nav class="subnav game-tablist" data-tablist aria-label="{name} sections">{tab_links}</nav>'
    def standalone_link(kind, label):
        return f'<div class="standalone-link"><a class="button" href="{slug}-{kind}.html">Open standalone {label} page <span aria-hidden="true">↗</span></a></div>'
    download_view = standalone_link('download', 'download') + f'<div class="download-shell"><div class="eyebrow">{g["status"]}</div><h2>Download {name}</h2><p>{g["short"]}</p>{download}</div>'
    support_view = standalone_link('support', 'support') + supportbody.split(subnav(g, 'Support'), 1)[1]
    privacy_view = standalone_link('privacy', 'privacy policy') + f'<div class="tab-intro"><h2>{name} privacy policy</h2><p>Effective and last updated: <time datetime="{DATE}">{UPDATED}</time></p><p>The <a href="privacy.html#website">website privacy notice</a> describes visits to this site.</p></div>' + policybody.split(subnav(g, 'Privacy policy'), 1)[1]
    panel_content = {'overview': overview_content, 'download': download_view,
                     'support': support_view, 'privacy': privacy_view}
    panels = ''.join(
        f'<section id="panel-{key}" class="tab-panel" data-panel="{key}"'
        + (' hidden' if key != 'overview' else '')
        + f'>{panel_content[key]}</section>' for key, _, _ in tab_items
    )
    page(slug + '.html', name + ' — Vertifold Studios', g['short'],
         overview_hero + f'<div data-game-tabs>{tab_nav}{panels}</div>', slug,
         game_tabs=True)


support_cards=''.join(f'<article class="directory-card {g["slug"]}"><div class="eyebrow">{g["status"]}</div><h2>{g["name"]}</h2><p>{g["math"]}, made playable.</p><a href="{g["slug"]}-support.html">Game support ↗</a><a href="{g["slug"]}-privacy.html">Privacy policy ↗</a><a href="{g["slug"]}-download.html">Download &amp; availability ↗</a></article>' for g in GAMES)
page('support.html','Player Support — Vertifold Studios','Get help with Color Surge, Traffic Tangle, and Cover Command. Contact Vertifold Studios for support, feedback, or privacy requests.',f'<div class="legal-hero"><div class="eyebrow">Here to help</div><h1>Let’s figure it out.</h1><p>Choose a game for troubleshooting, contact details, privacy information, and release status.</p></div><section class="directory-grid">{support_cards}</section><section class="section support-grid"><div class="support-card"><h2>Say hello.</h2><p>For general questions, feedback, or press enquiries, contact Jordan Turley at Vertifold Studios.</p><a href="{mail("Hello Vertifold Studios")}">{EMAIL}</a></div><div class="support-card"><h2>Questions about your data?</h2><p>Find game-specific policies and information about this website in our privacy hub.</p><a href="privacy.html">Privacy &amp; data ↗</a></div></section>')
privacy_cards=''.join(f'<article class="directory-card {g["slug"]}"><div class="eyebrow">{g["math"]}</div><h2>{g["name"]}</h2><a href="{g["slug"]}-privacy.html">Read the privacy policy ↗</a><a href="{g["slug"]}-privacy.html#choices">Privacy choices &amp; deletion ↗</a></article>' for g in GAMES)
page('privacy.html','Privacy & Data — Vertifold Studios','Privacy policies for all Vertifold Studios games, website privacy information, and ways to request access or deletion of your data.',f'''<div class="legal-hero"><div class="eyebrow">Privacy &amp; data</div><h1>A little clarity<br>goes a long way.</h1><p>Each game has its own policy explaining local saves, advertising services, and your privacy choices.</p></div><section class="directory-grid">{privacy_cards}</section><section class="section prose" id="website"><h2>Website privacy notice</h2><p>Effective and last updated: <time datetime="{DATE}">{UPDATED}</time></p><p>This website is operated by Jordan Turley as Vertifold Studios and hosted on GitHub Pages. It does not use analytics scripts, advertising trackers, embedded social media, web fonts from third parties, cookies, or browser storage. All illustrations and site assets are served with the site.</p><p>GitHub receives technical information, including visitors’ IP addresses, when serving the website for security and operational purposes. Its processing and retention are described in the <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub General Privacy Statement</a>. We do not run a separate visitor database.</p><p>External links take you to services such as app stores, Google, Apple, or Wikipedia, which have their own privacy practices. Clicking an email link opens your email application; nothing is sent until you choose to send it. When you contact us, we receive your address, message, and attachments. We use these to respond and retain correspondence for up to 12 months after resolution, unless earlier deletion is requested or longer retention is required by law or an ongoing dispute.</p><h2>Privacy requests</h2><p>Email <a href="{mail('Vertifold Studios website privacy request')}">{EMAIL}</a> for access, correction, or deletion of correspondence we hold, or questions about this site. State whether your request concerns the website or a particular game. We may need limited information to verify your request. Rights, including the ability to complain to a data protection authority, depend on applicable law. We cannot erase logs held independently by the hosting provider; please consult its privacy policy for its request process.</p></section>''')
page('404.html','Page Not Found — Vertifold Studios','Find your way back to Vertifold Studios games and support.','<section class="legal-hero"><div class="eyebrow">404 · A missing connection</div><h1>This path goes<br>off the graph.</h1><p>The page may have moved, or the address may have a typo. Let’s get you back to the puzzles.</p><div class="actions"><a class="button primary" href="/">Back to the studio ↗</a><a class="button" href="/support.html">Player support</a></div></section>',noindex=True)
# Root-relative assets make the custom error page work for missing nested URLs.
p=ROOT/'404.html'
s=p.read_text()
for prefix in ['assets/', 'index.html', 'support.html', 'privacy.html', 'color-surge.html', 'traffic-tangle.html', 'cover-command.html', 'favicon.ico']:
    s=s.replace('href="'+prefix, 'href="/'+prefix).replace('src="'+prefix,'src="/'+prefix)
p.write_text(s)
(ROOT/'CNAME').write_text('vertifold.studio\n')
(ROOT/'.nojekyll').touch()
(ROOT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+SITE+'/sitemap.xml\n')
urls=['index.html','support.html','privacy.html']+[g['slug']+suffix+'.html' for g in GAMES for suffix in ['', '-download','-support','-privacy']]
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join(f'<url><loc>{SITE}{"/" if u=="index.html" else "/"+u}</loc><lastmod>{DATE}</lastmod></url>\n' for u in urls)+'</urlset>\n')
print('Generated',len(urls)+1,'HTML pages.')
